import { createContext, useContext, useState, useEffect } from 'react';

export const ThemeContext = createContext();

export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState('default-mode');
  const [accentTheme, setAccentTheme] = useState(null);
  const [font, setFont] = useState('puvi');
  const [contrast, setContrast] = useState(false);
  const [direction, setDirection] = useState('ltr');
  const [textScale, setTextScale] = useState(3); // Default to 3 (100% scaling)

  // Available themes based on CSS classes
  const availableThemes = [
    { name: 'default-mode', label: 'Light', isDark: false },
    { name: 'dark-mode', label: 'Dark', isDark: true }
  ];

  // Available accent themes
  const availableAccentThemes = [
    { name: 'cardinal-theme', label: 'Cardinal' },
    { name: 'cobalt-theme', label: 'Cobalt' }
  ];

  // Function to apply theme classes to body
  const applyThemeClasses = (themeName, accentThemeName) => {
    const body = document.body;
    
    // Remove all theme classes
    const allThemeClasses = [
      'uls-default-mode', 'uls-dark-mode',
      'uls-cardinal-theme', 'uls-cobalt-theme',
      'uls-dark-cardinal-theme', 'uls-dark-cobalt-theme'
    ];
    allThemeClasses.forEach(className => body.classList.remove(className));
    
    // Apply base theme
    body.classList.add(`uls-${themeName}`);
    
    // Apply accent theme if specified
    if (accentThemeName) {
      if (themeName === 'dark-mode') {
        body.classList.add(`uls-dark-${accentThemeName}`);
      } else {
        body.classList.add(`uls-${accentThemeName}`);
      }
    }
    
    console.log(`✅ Applied theme: uls-${themeName}${accentThemeName ? ` + uls-${accentThemeName}` : ''}`);
  };

  // Load theme preferences from localStorage on mount
  useEffect(() => {
    const savedTheme = localStorage.getItem('uls-theme');
    const savedAccentTheme = localStorage.getItem('uls-accent-theme');
    const savedFont = localStorage.getItem('uls-font');
    const savedContrast = localStorage.getItem('uls-contrast');
    const savedDirection = localStorage.getItem('uls-direction');
    const savedTextScale = localStorage.getItem('uls-text-scale');

    if (savedTheme) setTheme(savedTheme);
    if (savedAccentTheme) setAccentTheme(savedAccentTheme);
    if (savedFont) setFont(savedFont);
    if (savedContrast) setContrast(savedContrast === 'true');
    if (savedDirection) setDirection(savedDirection);
    if (savedTextScale) setTextScale(parseFloat(savedTextScale));
  }, []);

  // Apply theme classes when theme or accent theme changes
  useEffect(() => {
    applyThemeClasses(theme, accentTheme);
  }, [theme, accentTheme]);

  useEffect(() => {
    // Update body classes and attributes when preferences change
    const body = document.body;
    const root = document.documentElement;
    
    // Handle font classes
    const fontClasses = ['puvi', 'lato', 'roboto', 'manrope', 'dyslexic'];
    fontClasses.forEach(fontClass => body.classList.remove(fontClass));
    body.classList.add(font);
    
    // Handle contrast class
    if (contrast) {
      body.classList.add('uls-high-contrast');
    } else {
      body.classList.remove('uls-high-contrast');
    }
    
    // Set direction attribute
    body.setAttribute('dir', direction);

    // Set text scale using CSS custom property
    // Convert level (1-8) to scale value (0.75-2.0)
    const scaleValues = [0.75, 0.875, 1, 1.125, 1.25, 1.5, 1.75, 2];
    const scaleValue = scaleValues[textScale - 1] || 1;
    root.style.setProperty('--uls-global-scale', scaleValue);

    // Save preferences to localStorage
    localStorage.setItem('uls-theme', theme);
    localStorage.setItem('uls-accent-theme', accentTheme || '');
    localStorage.setItem('uls-font', font);
    localStorage.setItem('uls-contrast', contrast.toString());
    localStorage.setItem('uls-direction', direction);
    localStorage.setItem('uls-text-scale', textScale.toString());
  }, [theme, accentTheme, font, contrast, direction, textScale]);

  // Function to get available themes for UI
  const getAvailableThemes = () => {
    return availableThemes;
  };

  // Function to get available accent themes for UI
  const getAvailableAccentThemes = () => {
    return availableAccentThemes;
  };

  // Function to set theme with accent
  const setThemeWithAccent = (themeName, accentThemeName = null) => {
    setTheme(themeName);
    setAccentTheme(accentThemeName);
  };

  // Function to set theme with mode (for theme switcher)
  const setThemeWithMode = (themeName, isDark) => {
    setTheme(themeName);
    // Note: isDark is derived from themeName, so we don't need to set it separately
  };

  // Function to check if current theme is dark
  const isDarkMode = theme === 'dark-mode';

  const value = {
    theme,
    setTheme,
    accentTheme,
    setAccentTheme,
    font,
    setFont,
    contrast,
    setContrast,
    direction,
    setDirection,
    textScale,
    setTextScale,
    isDarkMode,
    availableThemes,
    availableAccentThemes,
    getAvailableThemes,
    getAvailableAccentThemes,
    setThemeWithAccent,
    setThemeWithMode,
    toggleDarkMode: () => {
      if (isDarkMode) {
        // Switching to light mode
        setTheme('default-mode');
      } else {
        // Switching to dark mode
        setTheme('dark-mode');
      }
    },
    applyThemeClasses
  };

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
}; 